import sys
from collections import defaultdict

def main():
    counts = defaultdict(int)
    unique_count = 0
    result = []
    Q = int(sys.stdin.readline())
    for _ in range(Q):
        parts = sys.stdin.readline().split()
        if parts[0] == '1':
            x = int(parts[1])
            if counts[x] == 0:
                unique_count += 1
            counts[x] += 1
        elif parts[0] == '2':
            x = int(parts[1])
            prev = counts[x]
            counts[x] -= 1
            if prev == 1:
                unique_count -= 1
        elif parts[0] == '3':
            result.append(str(unique_count))
    print('\n'.join(result))

