from collections import defaultdict

def main():
    input = sys.stdin.read().split()
    Q = int(input[0])
    counts = defaultdict(int)
    output = []
    idx = 1
    for _ in range(Q):
        query_type = input[idx]
        if query_type == '1':
            x = int(input[idx+1])
            counts[x] += 1
            idx += 2
        elif query_type == '2':
            x = int(input[idx+1])
            counts[x] -= 1
            if counts[x] == 0:
                del counts[x]
            idx += 2
        else:
            output.append(str(len(counts)))
            idx += 1
    print('\n'.join(output))

